KIND = "questions"
SYSTEM = "nervous"
E = {
"ne-f804d1d2": {
"en": ["Which of the following about the glossopharyngeal nerve is FALSE?",
 ["It stimulates parotid secretion through the otic ganglion.", "It is the afferent limb of the gag reflex.", "It carries taste from the anterior two thirds of the tongue.", "It carries baroreceptor information from the carotid sinus.", "It carries both taste and general sensation from the posterior third of the tongue."],
 "IX carries taste and general sensation from the posterior third of the tongue, the pharyngeal mucosa and information from the carotid sinus and body; its only muscle is stylopharyngeus. Taste from the anterior two thirds of the tongue is carried by the chorda tympani (VII) and general sensation by the lingual nerve (V3).", []],
"fr": ["Laquelle des propositions suivantes concernant le nerf glossopharyngien est FAUSSE ?",
 ["Il stimule la sécrétion parotidienne par l'intermédiaire du ganglion otique.", "Il est la voie afférente du réflexe nauséeux.", "Il transmet le goût des deux tiers antérieurs de la langue.", "Il transmet l'information des barorécepteurs du sinus carotidien.", "Il transmet à la fois le goût et la sensibilité générale du tiers postérieur de la langue."],
 "Le IX transmet le goût et la sensibilité générale du tiers postérieur de la langue, la muqueuse pharyngée et les informations du sinus et du glomus carotidiens ; son seul muscle est le stylopharyngien. Le goût des deux tiers antérieurs de la langue passe par la corde du tympan (VII), la sensibilité générale par le nerf lingual (V3).", []],
"de": ["Welche Aussage über den N. glossopharyngeus ist FALSCH?",
 ["Er regt über das Ganglion oticum die Parotissekretion an.", "Er ist der afferente Schenkel des Würgereflexes.", "Er leitet den Geschmack der vorderen zwei Zungendrittel.", "Er leitet Barorezeptorinformationen aus dem Sinus caroticus.", "Er leitet Geschmack und allgemeine Sensibilität des hinteren Zungendrittels."],
 "IX leitet Geschmack und allgemeine Sensibilität des hinteren Zungendrittels, die Rachenschleimhaut sowie Informationen aus Sinus und Glomus caroticum; sein einziger Muskel ist der M. stylopharyngeus. Der Geschmack der vorderen zwei Zungendrittel läuft über die Chorda tympani (VII), die allgemeine Sensibilität über den N. lingualis (V3).", []],
"es": ["¿Cuál de las siguientes afirmaciones sobre el nervio glosofaríngeo es FALSA?",
 ["Estimula la secreción parotídea a través del ganglio ótico.", "Es la vía aferente del reflejo nauseoso.", "Lleva el gusto de los dos tercios anteriores de la lengua.", "Lleva información de los barorreceptores del seno carotídeo.", "Lleva el gusto y la sensibilidad general del tercio posterior de la lengua."],
 "El IX lleva el gusto y la sensibilidad general del tercio posterior de la lengua, la mucosa faríngea y la información del seno y el cuerpo carotídeos; su único músculo es el estilofaríngeo. El gusto de los dos tercios anteriores lo lleva la cuerda del tímpano (VII) y la sensibilidad general, el nervio lingual (V3).", []],
},
"ne-c4430a06": {
"en": ["When asked to say 'aah', the patient's uvula deviates to the right. Which nerve and side are affected?",
 ["Left vagus nerve", "Left facial nerve", "Right hypoglossal nerve", "Right vagus nerve", "Left glossopharyngeal nerve"],
 "The muscles of the soft palate (levator veli palatini and others) are supplied by the vagus nerve. With one side paralysed, the healthy side pulls the palate towards itself, so the uvula deviates to the healthy side, away from the lesion. The tongue, by contrast, deviates towards the side of the lesion.", []],
"fr": ["Lorsqu'on lui demande de dire « aah », la luette du patient dévie vers la droite. Quel nerf et quel côté sont atteints ?",
 ["Nerf vague gauche", "Nerf facial gauche", "Nerf hypoglosse droit", "Nerf vague droit", "Nerf glossopharyngien gauche"],
 "Les muscles du voile du palais (élévateur du voile, etc.) sont innervés par le nerf vague. En cas de paralysie d'un côté, le côté sain attire le voile vers lui : la luette dévie vers le côté sain, à l'opposé de la lésion. La langue, à l'inverse, dévie du côté de la lésion.", []],
"de": ["Bei der Aufforderung, „Aaa“ zu sagen, weicht das Zäpfchen (Uvula) des Patienten nach rechts ab. Welcher Nerv auf welcher Seite ist betroffen?",
 ["Linker N. vagus", "Linker N. facialis", "Rechter N. hypoglossus", "Rechter N. vagus", "Linker N. glossopharyngeus"],
 "Die Gaumensegelmuskeln (M. levator veli palatini u. a.) werden vom N. vagus innerviert. Bei einseitiger Lähmung zieht die gesunde Seite das Gaumensegel zu sich; die Uvula weicht zur gesunden Seite, also von der Läsion weg, ab. Die Zunge dagegen weicht zur Läsionsseite ab.", []],
"es": ["Al pedirle que diga «aaa», la úvula del paciente se desvía a la derecha. ¿Qué nervio y de qué lado está afectado?",
 ["Nervio vago izquierdo", "Nervio facial izquierdo", "Nervio hipogloso derecho", "Nervio vago derecho", "Nervio glosofaríngeo izquierdo"],
 "Los músculos del velo del paladar (elevador del velo y otros) están inervados por el vago. Si un lado está paralizado, el lado sano tira del paladar hacia sí, de modo que la úvula se desvía hacia el lado sano, opuesto a la lesión. La lengua, en cambio, se desvía hacia el lado de la lesión.", []],
},
"ne-bc679c52": {
"en": ["Under which structure does the left recurrent laryngeal nerve hook before turning upwards?",
 ["Left brachiocephalic vein", "Brachiocephalic trunk", "Arch of the aorta (just lateral to the ligamentum arteriosum)", "Left subclavian artery", "Left main bronchus"],
 "The left recurrent nerve hooks under the arch of the aorta beside the ligamentum arteriosum; the right recurrent nerve turns under the right subclavian artery. Because of its long course, the left nerve can be compressed by an aortic aneurysm, an enlarged left atrium or a lung tumour, causing hoarseness.", []],
"fr": ["Sous quelle structure le nerf laryngé récurrent gauche passe-t-il avant de remonter ?",
 ["Veine brachiocéphalique gauche", "Tronc brachiocéphalique", "Arc de l'aorte (juste en dehors du ligament artériel)", "Artère subclavière gauche", "Bronche principale gauche"],
 "Le nerf récurrent gauche contourne l'arc aortique à côté du ligament artériel ; le récurrent droit passe sous l'artère subclavière droite. En raison de son long trajet, le nerf gauche peut être comprimé par un anévrisme aortique, une dilatation de l'atrium gauche ou une tumeur pulmonaire, d'où une dysphonie.", []],
"de": ["Unter welcher Struktur schlingt sich der linke N. laryngeus recurrens, bevor er nach oben zurückläuft?",
 ["Linke V. brachiocephalica", "Truncus brachiocephalicus", "Arcus aortae (direkt lateral des Lig. arteriosum)", "Linke A. subclavia", "Linker Hauptbronchus"],
 "Der linke N. recurrens schlingt sich neben dem Lig. arteriosum unter dem Aortenbogen hindurch, der rechte unter der rechten A. subclavia. Wegen seines langen Verlaufs kann der linke Nerv durch ein Aortenaneurysma, einen vergrößerten linken Vorhof oder einen Lungentumor komprimiert werden und Heiserkeit verursachen.", []],
"es": ["¿Bajo qué estructura se curva el nervio laríngeo recurrente izquierdo antes de volver a ascender?",
 ["Vena braquiocefálica izquierda", "Tronco braquiocefálico", "Arco de la aorta (justo lateral al ligamento arterioso)", "Arteria subclavia izquierda", "Bronquio principal izquierdo"],
 "El recurrente izquierdo rodea el arco aórtico junto al ligamento arterioso; el derecho se curva bajo la arteria subclavia derecha. Por su largo trayecto, el nervio izquierdo puede comprimirse por un aneurisma aórtico, una aurícula izquierda dilatada o un tumor pulmonar, causando disfonía.", []],
},
"ne-e83d1843": {
"en": ["Which cranial nerves carry parasympathetic fibres?",
 ["III, VII, IX and X", "V, VII, IX and XI", "II, III, VII and XII", "VII, IX, X and XII", "III, IV, V and VI"],
 "The cranial parasympathetic outflow travels in four nerves: III (ciliary ganglion – pupil and accommodation), VII (pterygopalatine and submandibular ganglia), IX (otic ganglion – parotid) and X (thoracic and abdominal organs).", []],
"fr": ["Quels nerfs crâniens transportent des fibres parasympathiques ?",
 ["III, VII, IX et X", "V, VII, IX et XI", "II, III, VII et XII", "VII, IX, X et XII", "III, IV, V et VI"],
 "Le contingent parasympathique crânien emprunte quatre nerfs : III (ganglion ciliaire – pupille et accommodation), VII (ganglions ptérygopalatin et submandibulaire), IX (ganglion otique – parotide) et X (organes thoraciques et abdominaux).", []],
"de": ["Welche Hirnnerven führen parasympathische Fasern?",
 ["III, VII, IX und X", "V, VII, IX und XI", "II, III, VII und XII", "VII, IX, X und XII", "III, IV, V und VI"],
 "Der kraniale Parasympathikus verläuft in vier Nerven: III (Ganglion ciliare – Pupille und Akkommodation), VII (Ganglion pterygopalatinum und submandibulare), IX (Ganglion oticum – Parotis) und X (Brust- und Bauchorgane).", []],
"es": ["¿Qué nervios craneales llevan fibras parasimpáticas?",
 ["III, VII, IX y X", "V, VII, IX y XI", "II, III, VII y XII", "VII, IX, X y XII", "III, IV, V y VI"],
 "La salida parasimpática craneal viaja por cuatro nervios: III (ganglio ciliar – pupila y acomodación), VII (ganglios pterigopalatino y submandibular), IX (ganglio ótico – parótida) y X (órganos torácicos y abdominales).", []],
},
"ne-a9ee3049": {
"en": ["Which is the only cranial nerve that emerges from the dorsal (posterior) surface of the brainstem?",
 ["Accessory nerve", "Oculomotor nerve", "Trigeminal nerve", "Abducens nerve", "Trochlear nerve"],
 "The trochlear fibres cross in the midbrain and emerge from the dorsal surface below the inferior colliculi. It is the thinnest cranial nerve and has the longest intracranial course. It supplies the superior oblique of the opposite side.", []],
"fr": ["Quel est le seul nerf crânien qui émerge de la face dorsale (postérieure) du tronc cérébral ?",
 ["Nerf accessoire", "Nerf oculomoteur", "Nerf trijumeau", "Nerf abducens", "Nerf trochléaire"],
 "Les fibres du nerf trochléaire se croisent dans le mésencéphale et émergent de la face dorsale sous les colliculus inférieurs. C'est le nerf crânien le plus grêle et celui dont le trajet intracrânien est le plus long. Il innerve le muscle oblique supérieur controlatéral.", []],
"de": ["Welcher Hirnnerv tritt als einziger an der dorsalen (hinteren) Fläche des Hirnstamms aus?",
 ["N. accessorius", "N. oculomotorius", "N. trigeminus", "N. abducens", "N. trochlearis"],
 "Die Trochlearisfasern kreuzen im Mittelhirn und treten unterhalb der Colliculi inferiores dorsal aus. Er ist der dünnste Hirnnerv mit dem längsten intrakraniellen Verlauf und innerviert den M. obliquus superior der Gegenseite.", []],
"es": ["¿Cuál es el único nervio craneal que sale de la cara dorsal (posterior) del tronco del encéfalo?",
 ["Nervio accesorio", "Nervio oculomotor", "Nervio trigémino", "Nervio abducens", "Nervio troclear"],
 "Las fibras del troclear se cruzan en el mesencéfalo y salen por la cara dorsal por debajo de los colículos inferiores. Es el nervio craneal más fino y el de trayecto intracraneal más largo. Inerva el oblicuo superior del lado opuesto.", []],
},
"ne-e3ffe10b": {
"en": ["After squeezing a boil on the face a patient develops fever, periorbital oedema and proptosis; cavernous sinus thrombosis is suspected. Which cranial nerve is expected to be affected first, and why?",
 ["Maxillary nerve; because it lies in the floor of the sinus", "Oculomotor nerve; because it is highest in the lateral wall of the sinus", "Optic nerve; because it passes through the sinus", "Trochlear nerve; because it runs free inside the sinus", "Abducens nerve; because it runs free inside the sinus together with the internal carotid artery"],
 "In the lateral wall of the cavernous sinus lie, from above downwards, III, IV, V1 and V2; inside the sinus are the internal carotid artery and the abducens nerve. Abducens palsy (limited lateral gaze) is therefore often the first sign. The 'danger triangle' of the face communicates with the sinus through the ophthalmic veins.", []],
"fr": ["Après avoir pressé un furoncle du visage, un patient présente de la fièvre, un œdème périorbitaire et une exophtalmie ; on suspecte une thrombose du sinus caverneux. Quel nerf crânien devrait être atteint en premier, et pourquoi ?",
 ["Le nerf maxillaire, car il est situé dans le plancher du sinus", "Le nerf oculomoteur, car il est le plus haut dans la paroi latérale du sinus", "Le nerf optique, car il traverse le sinus", "Le nerf trochléaire, car il chemine librement dans le sinus", "Le nerf abducens, car il chemine librement dans le sinus avec l'artère carotide interne"],
 "Dans la paroi latérale du sinus caverneux se trouvent de haut en bas le III, le IV, le V1 et le V2 ; dans la lumière du sinus, l'artère carotide interne et le nerf abducens. La paralysie du VI (limitation du regard latéral) est donc souvent le premier signe. Le « triangle dangereux » de la face communique avec le sinus par les veines ophtalmiques.", []],
"de": ["Nach dem Ausdrücken eines Furunkels im Gesicht entwickelt ein Patient Fieber, ein Lidödem und einen Exophthalmus; man vermutet eine Sinus-cavernosus-Thrombose. Welcher Hirnnerv ist voraussichtlich zuerst betroffen und warum?",
 ["N. maxillaris, da er am Boden des Sinus liegt", "N. oculomotorius, da er in der Seitenwand des Sinus am höchsten liegt", "N. opticus, da er durch den Sinus zieht", "N. trochlearis, da er frei im Sinus verläuft", "N. abducens, da er zusammen mit der A. carotis interna frei im Sinus verläuft"],
 "In der Seitenwand des Sinus cavernosus liegen von oben nach unten III, IV, V1 und V2; im Sinus selbst verlaufen A. carotis interna und N. abducens. Daher ist die Abduzensparese (eingeschränkter Seitblick) oft das erste Zeichen. Das „gefährliche Dreieck“ des Gesichts steht über die Vv. ophthalmicae mit dem Sinus in Verbindung.", []],
"es": ["Tras exprimir un forúnculo de la cara, un paciente presenta fiebre, edema periorbitario y proptosis; se sospecha una trombosis del seno cavernoso. ¿Qué nervio craneal se espera que se afecte primero y por qué?",
 ["El nervio maxilar, porque está en el suelo del seno", "El nervio oculomotor, porque es el más alto en la pared lateral del seno", "El nervio óptico, porque atraviesa el seno", "El nervio troclear, porque discurre libre dentro del seno", "El nervio abducens, porque discurre libre dentro del seno junto con la arteria carótida interna"],
 "En la pared lateral del seno cavernoso están, de arriba abajo, el III, el IV, el V1 y el V2; dentro del seno, la carótida interna y el nervio abducens. Por eso la parálisis del VI (limitación de la mirada lateral) suele ser el primer signo. El «triángulo peligroso» de la cara comunica con el seno por las venas oftálmicas.", []],
},
"ne-eed7e04e": {
"en": ["How are the cords of the brachial plexus named?",
 ["By their position relative to the second part of the axillary artery", "By their position relative to scalenus anterior", "By their position relative to the clavicle", "By the compartment they supply", "By the spinal segments they come from"],
 "The lateral, medial and posterior cords surround the second part of the axillary artery behind pectoralis minor and are named after their position relative to it. The roots (C5–T1) lie in the scalene gap, the trunks in the posterior triangle and the divisions behind the clavicle.", []],
"fr": ["Comment sont nommés les faisceaux (cordons) du plexus brachial ?",
 ["Selon leur position par rapport à la deuxième portion de l'artère axillaire", "Selon leur position par rapport au muscle scalène antérieur", "Selon leur position par rapport à la clavicule", "Selon la loge qu'ils innervent", "Selon les segments médullaires dont ils proviennent"],
 "Les faisceaux latéral, médial et postérieur entourent la deuxième portion de l'artère axillaire en arrière du petit pectoral et tirent leur nom de leur position par rapport à elle. Les racines (C5–T1) sont dans le défilé des scalènes, les troncs dans le triangle postérieur et les divisions en arrière de la clavicule.", []],
"de": ["Wonach werden die Faszikel des Plexus brachialis benannt?",
 ["Nach ihrer Lage zum zweiten Abschnitt der A. axillaris", "Nach ihrer Lage zum M. scalenus anterior", "Nach ihrer Lage zur Klavikula", "Nach dem Kompartiment, das sie versorgen", "Nach den Rückenmarksegmenten, aus denen sie stammen"],
 "Fasciculus lateralis, medialis und posterior umgeben hinter dem M. pectoralis minor den zweiten Abschnitt der A. axillaris und sind nach ihrer Lage zu ihr benannt. Die Wurzeln (C5–T1) liegen in der Skalenuslücke, die Trunci im seitlichen Halsdreieck, die Divisionen hinter der Klavikula.", []],
"es": ["¿Cómo se nombran los fascículos del plexo braquial?",
 ["Por su posición respecto a la segunda porción de la arteria axilar", "Por su posición respecto al escaleno anterior", "Por su posición respecto a la clavícula", "Por el compartimento que inervan", "Por los segmentos medulares de los que proceden"],
 "Los fascículos lateral, medial y posterior rodean la segunda porción de la arteria axilar por detrás del pectoral menor y reciben su nombre por su posición respecto a ella. Las raíces (C5–T1) están en el desfiladero de los escalenos, los troncos en el triángulo posterior y las divisiones detrás de la clavícula.", []],
},
"ne-3c25db81": {
"en": ["After a difficult delivery with shoulder dystocia, the baby's arm lies adducted and internally rotated at the side, with the elbow extended and the forearm pronated (the 'waiter's tip' position). Which structure is affected?",
 ["Musculocutaneous nerve", "Lower trunk of the brachial plexus (C8–T1) – Klumpke palsy", "Upper trunk of the brachial plexus (C5–C6) – Erb–Duchenne palsy", "Axillary nerve", "Posterior cord"],
 "Forcibly widening the angle between head and shoulder stretches the upper trunk. Deltoid, supraspinatus, infraspinatus (abduction and external rotation), biceps and brachialis (elbow flexion) and the supinators are paralysed, and the arm takes up the typical position.", []],
"fr": ["Après un accouchement difficile avec dystocie des épaules, le bras du bébé est le long du corps en adduction et rotation interne, coude en extension et avant-bras en pronation (position du « pourboire du serveur »). Quelle structure est atteinte ?",
 ["Nerf musculocutané", "Tronc inférieur du plexus brachial (C8–T1) – paralysie de Klumpke", "Tronc supérieur du plexus brachial (C5–C6) – paralysie d'Erb–Duchenne", "Nerf axillaire", "Faisceau postérieur"],
 "L'écartement forcé de la tête et de l'épaule étire le tronc supérieur. Le deltoïde, le supra-épineux, l'infra-épineux (abduction et rotation externe), le biceps et le brachial (flexion du coude) et les supinateurs sont paralysés ; le bras prend la position typique.", []],
"de": ["Nach einer schweren Geburt mit Schulterdystokie liegt der Arm des Babys adduziert und innenrotiert am Körper, der Ellbogen gestreckt, der Unterarm proniert („Kellnertrinkgeld“-Stellung). Welche Struktur ist betroffen?",
 ["N. musculocutaneus", "Unterer Truncus des Plexus brachialis (C8–T1) – Klumpke-Lähmung", "Oberer Truncus des Plexus brachialis (C5–C6) – Erb-Duchenne-Lähmung", "N. axillaris", "Fasciculus posterior"],
 "Das gewaltsame Auseinanderziehen von Kopf und Schulter überdehnt den oberen Truncus. Deltoideus, Supraspinatus, Infraspinatus (Abduktion und Außenrotation), Bizeps und Brachialis (Ellbogenbeugung) sowie die Supinatoren sind gelähmt; der Arm nimmt die typische Stellung ein.", []],
"es": ["Tras un parto difícil con distocia de hombros, el brazo del bebé queda junto al cuerpo en aducción y rotación interna, con el codo extendido y el antebrazo en pronación (posición de «propina del camarero»). ¿Qué estructura está afectada?",
 ["Nervio musculocutáneo", "Tronco inferior del plexo braquial (C8–T1) – parálisis de Klumpke", "Tronco superior del plexo braquial (C5–C6) – parálisis de Erb–Duchenne", "Nervio axilar", "Fascículo posterior"],
 "La separación forzada entre la cabeza y el hombro estira el tronco superior. Se paralizan el deltoides, el supraespinoso, el infraespinoso (abducción y rotación externa), el bíceps y el braquial (flexión del codo) y los supinadores; el brazo adopta la posición típica.", []],
},
"ne-7352de71": {
"en": ["A patient who grabbed a branch while falling, so that the arm was forcibly pulled upwards, develops clawing of the hand, wasting of the intrinsic muscles, sensory loss on the inner forearm, and ptosis with miosis on the same side. What is the lesion?",
 ["Lower trunk of the brachial plexus (C8–T1) – Klumpke palsy", "Upper trunk of the brachial plexus (C5–C6)", "Injury of the radial nerve in the axilla", "Lateral cord", "Injury of the median nerve at the wrist"],
 "Forcible traction of the abducted arm stretches the lower trunk (C8–T1): the intrinsic muscles of the hand are paralysed and a claw hand develops. Involvement of the sympathetic fibres near the T1 root (stellate ganglion) explains the Horner syndrome.", []],
"fr": ["Un patient qui s'est rattrapé à une branche en tombant, le bras tiré violemment vers le haut, présente une main en griffe, une amyotrophie des muscles intrinsèques, une perte sensitive de la face médiale de l'avant-bras ainsi qu'un ptosis et un myosis du même côté. Quelle est la lésion ?",
 ["Tronc inférieur du plexus brachial (C8–T1) – paralysie de Klumpke", "Tronc supérieur du plexus brachial (C5–C6)", "Lésion du nerf radial dans l'aisselle", "Faisceau latéral", "Lésion du nerf médian au poignet"],
 "La traction forcée du bras en abduction étire le tronc inférieur (C8–T1) : les muscles intrinsèques de la main sont paralysés et une main en griffe apparaît. L'atteinte des fibres sympathiques proches de la racine T1 (ganglion stellaire) explique le syndrome de Claude Bernard–Horner.", []],
"de": ["Ein Patient, der sich im Fallen an einem Ast festhielt, wobei der Arm gewaltsam nach oben gezogen wurde, entwickelt eine Krallenhand, eine Atrophie der Handbinnenmuskeln, einen Sensibilitätsausfall an der Unterarminnenseite sowie Ptosis und Miosis auf derselben Seite. Welche Läsion liegt vor?",
 ["Unterer Truncus des Plexus brachialis (C8–T1) – Klumpke-Lähmung", "Oberer Truncus des Plexus brachialis (C5–C6)", "Verletzung des N. radialis in der Achsel", "Fasciculus lateralis", "Verletzung des N. medianus am Handgelenk"],
 "Gewaltsamer Zug am abduzierten Arm überdehnt den unteren Truncus (C8–T1): Die Handbinnenmuskeln sind gelähmt, es entsteht eine Krallenhand. Die Mitbeteiligung der sympathischen Fasern nahe der Wurzel T1 (Ganglion stellatum) erklärt das Horner-Syndrom.", []],
"es": ["Un paciente que se agarró a una rama al caer, de modo que el brazo fue traccionado con fuerza hacia arriba, presenta mano en garra, atrofia de los músculos intrínsecos, pérdida sensitiva en la cara interna del antebrazo y ptosis con miosis del mismo lado. ¿Cuál es la lesión?",
 ["Tronco inferior del plexo braquial (C8–T1) – parálisis de Klumpke", "Tronco superior del plexo braquial (C5–C6)", "Lesión del nervio radial en la axila", "Fascículo lateral", "Lesión del nervio mediano en la muñeca"],
 "La tracción forzada del brazo en abducción estira el tronco inferior (C8–T1): se paralizan los músculos intrínsecos de la mano y aparece la mano en garra. La afectación de las fibras simpáticas próximas a la raíz T1 (ganglio estrellado) explica el síndrome de Horner.", []],
},
"ne-abc65d94": {
"en": ["Which of the following nerves does NOT arise from the posterior cord of the brachial plexus?",
 ["Upper subscapular nerve", "Thoracodorsal nerve", "Musculocutaneous nerve", "Radial nerve", "Axillary nerve"],
 "The posterior cord gives the branches supplying the back of the shoulder and arm: the upper and lower subscapular, thoracodorsal, axillary and radial nerves. The musculocutaneous nerve arises from the lateral cord and supplies the anterior compartment of the arm.", []],
"fr": ["Lequel des nerfs suivants NE naît PAS du faisceau postérieur du plexus brachial ?",
 ["Nerf subscapulaire supérieur", "Nerf thoracodorsal", "Nerf musculocutané", "Nerf radial", "Nerf axillaire"],
 "Le faisceau postérieur donne les branches destinées à la face postérieure de l'épaule et du bras : nerfs subscapulaires supérieur et inférieur, thoracodorsal, axillaire et radial. Le nerf musculocutané naît du faisceau latéral et innerve la loge antérieure du bras.", []],
"de": ["Welcher der folgenden Nerven geht NICHT aus dem Fasciculus posterior des Plexus brachialis hervor?",
 ["N. subscapularis superior", "N. thoracodorsalis", "N. musculocutaneus", "N. radialis", "N. axillaris"],
 "Der Fasciculus posterior gibt die Äste für die Rückseite von Schulter und Arm ab: Nn. subscapulares superior und inferior, N. thoracodorsalis, N. axillaris und N. radialis. Der N. musculocutaneus entspringt dem Fasciculus lateralis und versorgt das vordere Oberarmkompartiment.", []],
"es": ["¿Cuál de los siguientes nervios NO procede del fascículo posterior del plexo braquial?",
 ["Nervio subescapular superior", "Nervio toracodorsal", "Nervio musculocutáneo", "Nervio radial", "Nervio axilar"],
 "El fascículo posterior da las ramas para la cara posterior del hombro y el brazo: los nervios subescapulares superior e inferior, el toracodorsal, el axilar y el radial. El musculocutáneo nace del fascículo lateral e inerva el compartimento anterior del brazo.", []],
},
"ne-b856c3f9": {
"en": ["From which parts of the brachial plexus is the median nerve formed?",
 ["Lateral cord and posterior cord", "Lateral cord and medial cord", "Lateral cord only", "Upper trunk and middle trunk", "Posterior cord and medial cord"],
 "The median nerve is formed by two roots from the lateral and medial cords that join in front of the axillary artery (C6–T1, sometimes with C5 fibres). It gives no branches in the arm; it supplies most of the forearm flexors and the thenar muscles.", []],
"fr": ["À partir de quelles parties du plexus brachial le nerf médian est-il formé ?",
 ["Faisceau latéral et faisceau postérieur", "Faisceau latéral et faisceau médial", "Faisceau latéral seul", "Tronc supérieur et tronc moyen", "Faisceau postérieur et faisceau médial"],
 "Le nerf médian est formé par la réunion, en avant de l'artère axillaire, de deux racines issues des faisceaux latéral et médial (C6–T1, parfois avec des fibres de C5). Il ne donne aucune branche au bras ; il innerve la plupart des fléchisseurs de l'avant-bras et les muscles thénariens.", []],
"de": ["Aus welchen Teilen des Plexus brachialis entsteht der N. medianus?",
 ["Fasciculus lateralis und Fasciculus posterior", "Fasciculus lateralis und Fasciculus medialis", "Nur Fasciculus lateralis", "Truncus superior und Truncus medius", "Fasciculus posterior und Fasciculus medialis"],
 "Der N. medianus entsteht durch Vereinigung zweier Wurzeln aus Fasciculus lateralis und medialis vor der A. axillaris (C6–T1, evtl. auch C5-Fasern; Medianusgabel). Am Oberarm gibt er keine Äste ab; er versorgt die meisten Unterarmbeuger und die Thenarmuskeln.", []],
"es": ["¿A partir de qué partes del plexo braquial se forma el nervio mediano?",
 ["Fascículo lateral y fascículo posterior", "Fascículo lateral y fascículo medial", "Solo el fascículo lateral", "Tronco superior y tronco medio", "Fascículo posterior y fascículo medial"],
 "El nervio mediano se forma por la unión, delante de la arteria axilar, de dos raíces de los fascículos lateral y medial (C6–T1, a veces con fibras de C5). No da ramas en el brazo; inerva la mayoría de los flexores del antebrazo y los músculos tenares.", []],
},
"ne-cd2e97f1": {
"en": ["Which nerves give no branches at all in the arm (brachium)?",
 ["Ulnar nerve and radial nerve", "Musculocutaneous nerve and median nerve", "Axillary nerve and radial nerve", "Radial nerve and musculocutaneous nerve", "Median nerve and ulnar nerve"],
 "Although the median and ulnar nerves run through the arm, they give no motor or sensory branches there; their branches are in the forearm and hand. The anterior compartment of the arm is supplied by the musculocutaneous nerve and the posterior compartment by the radial nerve.", []],
"fr": ["Quels nerfs ne donnent aucune branche au bras ?",
 ["Nerf ulnaire et nerf radial", "Nerf musculocutané et nerf médian", "Nerf axillaire et nerf radial", "Nerf radial et nerf musculocutané", "Nerf médian et nerf ulnaire"],
 "Bien qu'ils traversent le bras, les nerfs médian et ulnaire n'y donnent aucune branche motrice ou sensitive ; leurs branches sont à l'avant-bras et à la main. La loge antérieure du bras est innervée par le nerf musculocutané, la loge postérieure par le nerf radial.", []],
"de": ["Welche Nerven geben am Oberarm (Brachium) überhaupt keine Äste ab?",
 ["N. ulnaris und N. radialis", "N. musculocutaneus und N. medianus", "N. axillaris und N. radialis", "N. radialis und N. musculocutaneus", "N. medianus und N. ulnaris"],
 "N. medianus und N. ulnaris verlaufen zwar am Oberarm, geben dort aber keine motorischen oder sensiblen Äste ab; ihre Äste liegen an Unterarm und Hand. Das vordere Oberarmkompartiment versorgt der N. musculocutaneus, das hintere der N. radialis.", []],
"es": ["¿Qué nervios no dan ninguna rama en el brazo?",
 ["Nervio cubital y nervio radial", "Nervio musculocutáneo y nervio mediano", "Nervio axilar y nervio radial", "Nervio radial y nervio musculocutáneo", "Nervio mediano y nervio cubital"],
 "Aunque el mediano y el cubital recorren el brazo, no dan allí ramas motoras ni sensitivas; sus ramas están en el antebrazo y la mano. El compartimento anterior del brazo lo inerva el musculocutáneo y el posterior, el radial.", []],
},
"ne-cfd5de8f": {
"en": ["Which of the following dermatome pairings is wrong?",
 ["T10 – umbilicus", "S1 – lateral edge of the foot and heel", "L1 – groin", "C8 – thumb", "T4 – nipple"],
 "In the hand the thumb is C6, the middle finger C7 and the little finger C8. On the trunk T4 is the nipple, T10 the umbilicus and L1 the groin; on the leg L4 is the medial malleolus, L5 the dorsum of the foot and big toe, and S1 the lateral edge of the foot and the heel.", []],
"fr": ["Laquelle des correspondances de dermatomes suivantes est fausse ?",
 ["T10 – ombilic", "S1 – bord latéral du pied et talon", "L1 – région inguinale", "C8 – pouce", "T4 – mamelon"],
 "À la main, le pouce correspond à C6, le majeur à C7 et l'auriculaire à C8. Au tronc, T4 correspond au mamelon, T10 à l'ombilic et L1 à l'aine ; au membre inférieur, L4 à la malléole médiale, L5 au dos du pied et au gros orteil, S1 au bord latéral du pied et au talon.", []],
"de": ["Welche der folgenden Dermatomzuordnungen ist falsch?",
 ["T10 – Nabel", "S1 – Fußaußenrand und Ferse", "L1 – Leistenregion", "C8 – Daumen", "T4 – Brustwarze"],
 "An der Hand gehört der Daumen zu C6, der Mittelfinger zu C7 und der Kleinfinger zu C8. Am Rumpf entspricht T4 der Brustwarze, T10 dem Nabel und L1 der Leiste; am Bein L4 dem Innenknöchel, L5 dem Fußrücken und der Großzehe, S1 dem Fußaußenrand und der Ferse.", []],
"es": ["¿Cuál de las siguientes correspondencias de dermatomas es incorrecta?",
 ["T10 – ombligo", "S1 – borde lateral del pie y talón", "L1 – ingle", "C8 – pulgar", "T4 – pezón"],
 "En la mano el pulgar es C6, el dedo medio C7 y el meñique C8. En el tronco T4 es el pezón, T10 el ombligo y L1 la ingle; en la pierna L4 es el maléolo medial, L5 el dorso del pie y el primer dedo, y S1 el borde lateral del pie y el talón.", []],
},
"ne-78ef009f": {
"en": ["An obese patient who wears a tight belt has burning, numbness and tingling over the anterolateral thigh; muscle power and reflexes are normal. Which nerve is compressed?",
 ["Lateral femoral cutaneous nerve", "Femoral nerve", "Genitofemoral nerve", "Saphenous nerve", "Obturator nerve"],
 "Meralgia paraesthetica: the purely sensory lateral femoral cutaneous nerve (L2–L3) is compressed as it passes under the inguinal ligament just medial to the ASIS. Because it has no motor fibres, there is no weakness.", []],
"fr": ["Un patient obèse portant une ceinture serrée ressent des brûlures, un engourdissement et des fourmillements à la face antérolatérale de la cuisse ; la force et les réflexes sont normaux. Quel nerf est comprimé ?",
 ["Nerf cutané latéral de la cuisse", "Nerf fémoral", "Nerf génitofémoral", "Nerf saphène", "Nerf obturateur"],
 "Méralgie paresthésique : le nerf cutané latéral de la cuisse (L2–L3), purement sensitif, est comprimé lors de son passage sous le ligament inguinal juste en dedans de l'EIAS. Ne contenant pas de fibres motrices, il ne donne pas de déficit moteur.", []],
"de": ["Ein adipöser Patient mit eng sitzendem Gürtel hat Brennen, Taubheit und Kribbeln an der Vorderaußenseite des Oberschenkels; Kraft und Reflexe sind normal. Welcher Nerv ist eingeklemmt?",
 ["N. cutaneus femoris lateralis", "N. femoralis", "N. genitofemoralis", "N. saphenus", "N. obturatorius"],
 "Meralgia paraesthetica: Der rein sensible N. cutaneus femoris lateralis (L2–L3) wird beim Durchtritt unter dem Leistenband direkt medial der Spina iliaca anterior superior komprimiert. Da er keine motorischen Fasern führt, tritt keine Schwäche auf.", []],
"es": ["Un paciente obeso que lleva un cinturón apretado tiene ardor, entumecimiento y hormigueo en la cara anterolateral del muslo; la fuerza y los reflejos son normales. ¿Qué nervio está comprimido?",
 ["Nervio cutáneo femoral lateral", "Nervio femoral", "Nervio genitofemoral", "Nervio safeno", "Nervio obturador"],
 "Meralgia parestésica: el nervio cutáneo femoral lateral (L2–L3), puramente sensitivo, se comprime al pasar bajo el ligamento inguinal justo medial a la EIAS. Como no tiene fibras motoras, no hay debilidad.", []],
},
"ne-4b8d4357": {
"en": ["Which of the following is NOT expected after a femoral nerve injury?",
 ["Sensory loss on the front of the thigh", "Marked weakness of thigh adduction", "Weakness of knee extension", "Sensory loss on the medial side of the leg", "Loss of the patellar reflex"],
 "The femoral nerve (L2–L4) supplies quadriceps, sartorius, iliacus and pectineus, and carries sensation from the front of the thigh and, through the saphenous nerve, from the medial side of the leg. The adductors are supplied by the obturator nerve.", []],
"fr": ["Lequel des signes suivants N'est PAS attendu après une lésion du nerf fémoral ?",
 ["Perte sensitive de la face antérieure de la cuisse", "Faiblesse nette de l'adduction de la cuisse", "Faiblesse de l'extension du genou", "Perte sensitive de la face médiale de la jambe", "Abolition du réflexe rotulien"],
 "Le nerf fémoral (L2–L4) innerve le quadriceps, le sartorius, l'iliaque et le pectiné ; il assure la sensibilité de la face antérieure de la cuisse et, par le nerf saphène, de la face médiale de la jambe. Les adducteurs sont innervés par le nerf obturateur.", []],
"de": ["Was ist bei einer Verletzung des N. femoralis NICHT zu erwarten?",
 ["Sensibilitätsausfall an der Oberschenkelvorderseite", "Deutliche Schwäche der Oberschenkeladduktion", "Schwäche der Kniestreckung", "Sensibilitätsausfall an der Unterschenkelinnenseite", "Ausfall des Patellarsehnenreflexes"],
 "Der N. femoralis (L2–L4) innerviert Quadrizeps, Sartorius, Iliacus und Pectineus und leitet die Sensibilität der Oberschenkelvorderseite sowie über den N. saphenus der Unterschenkelinnenseite. Die Adduktoren werden vom N. obturatorius innerviert.", []],
"es": ["¿Cuál de los siguientes NO es de esperar tras una lesión del nervio femoral?",
 ["Pérdida sensitiva en la cara anterior del muslo", "Debilidad marcada de la aducción del muslo", "Debilidad de la extensión de la rodilla", "Pérdida sensitiva en la cara medial de la pierna", "Pérdida del reflejo rotuliano"],
 "El nervio femoral (L2–L4) inerva el cuádriceps, el sartorio, el ilíaco y el pectíneo, y recoge la sensibilidad de la cara anterior del muslo y, por el nervio safeno, de la cara medial de la pierna. Los aductores los inerva el nervio obturador.", []],
},
"ne-1b1b302a": {
"en": ["After prolonged pelvic surgery a patient has difficulty bringing the legs together and numbness over a small area on the inner thigh. Which nerve was injured?",
 ["Obturator nerve", "Femoral nerve", "Genitofemoral nerve", "Pudendal nerve", "Superior gluteal nerve"],
 "The obturator nerve (L2–L4) runs on the lateral pelvic wall, near the ovarian fossa, and enters the obturator canal. It can be injured in pelvic surgery, by tumours or in difficult labour; the thigh adductors weaken and sensation is lost on the inner thigh.", []],
"fr": ["Après une longue chirurgie pelvienne, une patiente a du mal à rapprocher les jambes et présente un engourdissement d'une petite zone de la face interne de la cuisse. Quel nerf a été lésé ?",
 ["Nerf obturateur", "Nerf fémoral", "Nerf génitofémoral", "Nerf pudendal", "Nerf glutéal supérieur"],
 "Le nerf obturateur (L2–L4) chemine sur la paroi latérale du pelvis, près de la fossette ovarienne, puis entre dans le canal obturateur. Il peut être lésé lors d'une chirurgie pelvienne, par une tumeur ou lors d'un accouchement difficile ; les adducteurs de la cuisse s'affaiblissent et la sensibilité de la face interne de la cuisse est perdue.", []],
"de": ["Nach einer langen Beckenoperation hat eine Patientin Mühe, die Beine zusammenzuführen, und ein kleines Taubheitsareal an der Oberschenkelinnenseite. Welcher Nerv wurde verletzt?",
 ["N. obturatorius", "N. femoralis", "N. genitofemoralis", "N. pudendus", "N. gluteus superior"],
 "Der N. obturatorius (L2–L4) verläuft an der seitlichen Beckenwand nahe der Fossa ovarica und tritt in den Canalis obturatorius ein. Er kann bei Beckenoperationen, durch Tumoren oder bei schwierigen Geburten verletzt werden; die Adduktoren werden schwach und die Sensibilität an der Oberschenkelinnenseite fällt aus.", []],
"es": ["Tras una cirugía pélvica prolongada una paciente tiene dificultad para juntar las piernas y entumecimiento en una pequeña zona de la cara interna del muslo. ¿Qué nervio se lesionó?",
 ["Nervio obturador", "Nervio femoral", "Nervio genitofemoral", "Nervio pudendo", "Nervio glúteo superior"],
 "El nervio obturador (L2–L4) recorre la pared lateral de la pelvis, cerca de la fosa ovárica, y entra en el conducto obturador. Puede lesionarse en la cirugía pélvica, por tumores o en partos difíciles; se debilitan los aductores del muslo y se pierde la sensibilidad de su cara interna.", []],
},
"ne-96063403": {
"en": ["At what level does the sciatic nerve most often divide into its two terminal branches (tibial and common fibular nerves)?",
 ["As it leaves the greater sciatic foramen", "At the very top of the thigh, at the gluteal fold", "At the neck of the fibula", "Behind the medial malleolus", "At the upper angle of the popliteal fossa"],
 "The sciatic nerve (L4–S3), the thickest nerve in the body, usually divides at the apex of the popliteal fossa. Sometimes the division is higher and the fibular part pierces piriformis.", []],
"fr": ["À quel niveau le nerf sciatique se divise-t-il le plus souvent en ses deux branches terminales (nerf tibial et nerf fibulaire commun) ?",
 ["À sa sortie du grand foramen ischiatique", "Tout en haut de la cuisse, au pli fessier", "Au col de la fibula", "En arrière de la malléole médiale", "À l'angle supérieur de la fosse poplitée"],
 "Le nerf sciatique (L4–S3), le plus gros nerf du corps, se divise habituellement au sommet de la fosse poplitée. Parfois la division est plus haute et la partie fibulaire traverse le muscle piriforme.", []],
"de": ["Auf welcher Höhe teilt sich der N. ischiadicus am häufigsten in seine beiden Endäste (N. tibialis und N. fibularis communis)?",
 ["Beim Austritt aus dem Foramen ischiadicum majus", "Ganz oben am Oberschenkel, an der Gesäßfalte", "Am Fibulahals", "Hinter dem Malleolus medialis", "Am oberen Winkel der Fossa poplitea"],
 "Der N. ischiadicus (L4–S3), der dickste Nerv des Körpers, teilt sich meist an der Spitze der Kniekehle. Manchmal erfolgt die Teilung höher, und der fibulare Anteil durchbohrt den M. piriformis.", []],
"es": ["¿A qué nivel se divide con más frecuencia el nervio ciático en sus dos ramas terminales (nervio tibial y nervio peroneo común)?",
 ["Al salir del agujero ciático mayor", "En la parte más alta del muslo, en el pliegue glúteo", "En el cuello del peroné", "Detrás del maléolo medial", "En el ángulo superior de la fosa poplítea"],
 "El nervio ciático (L4–S3), el más grueso del cuerpo, suele dividirse en el vértice de la fosa poplítea. A veces la división es más alta y la porción peronea atraviesa el piriforme.", []],
},
"ne-7800f94a": {
"en": ["Which of the following results from injury to the tibial nerve in the popliteal fossa?",
 ["Foot drop and sensory loss on the dorsum of the foot", "Sensory loss on the medial side of the leg", "Loss of plantar flexion of the foot and of toe flexion, sensory loss on the sole", "Loss of knee extension", "Loss of eversion of the foot"],
 "The tibial nerve supplies the posterior compartment muscles (triceps surae, tibialis posterior, long flexors) and, through its plantar branches, the muscles of the sole. After injury the foot is held in dorsiflexion and eversion (calcaneovalgus), the patient cannot walk on tiptoe and sensation on the sole is lost.", []],
"fr": ["Laquelle des conséquences suivantes résulte d'une lésion du nerf tibial dans la fosse poplitée ?",
 ["Pied tombant et perte sensitive du dos du pied", "Perte sensitive de la face médiale de la jambe", "Perte de la flexion plantaire du pied et de la flexion des orteils, perte sensitive de la plante", "Perte de l'extension du genou", "Perte de l'éversion du pied"],
 "Le nerf tibial innerve les muscles de la loge postérieure (triceps sural, tibial postérieur, longs fléchisseurs) et, par ses branches plantaires, les muscles de la plante. Après lésion, le pied reste en flexion dorsale et éversion (talus valgus), la marche sur la pointe est impossible et la sensibilité plantaire est perdue.", []],
"de": ["Welche Folge hat eine Verletzung des N. tibialis in der Kniekehle?",
 ["Fallfuß und Sensibilitätsausfall am Fußrücken", "Sensibilitätsausfall an der Unterschenkelinnenseite", "Ausfall der Plantarflexion des Fußes und der Zehenbeugung, Sensibilitätsausfall an der Fußsohle", "Ausfall der Kniestreckung", "Ausfall der Fußeversion"],
 "Der N. tibialis innerviert die Muskeln der hinteren Loge (Triceps surae, Tibialis posterior, lange Beuger) und über die Plantarnerven die Fußsohlenmuskeln. Bei Schädigung steht der Fuß in Dorsalextension und Eversion (Hackenfuß), Zehenspitzengang ist unmöglich und die Sohlensensibilität fällt aus.", []],
"es": ["¿Cuál de las siguientes resulta de una lesión del nervio tibial en la fosa poplítea?",
 ["Pie caído y pérdida sensitiva en el dorso del pie", "Pérdida sensitiva en la cara medial de la pierna", "Pérdida de la flexión plantar del pie y de la flexión de los dedos, pérdida sensitiva en la planta", "Pérdida de la extensión de la rodilla", "Pérdida de la eversión del pie"],
 "El nervio tibial inerva los músculos del compartimento posterior (tríceps sural, tibial posterior, flexores largos) y, por sus ramas plantares, los músculos de la planta. Tras su lesión el pie queda en flexión dorsal y eversión (pie talo valgo), no se puede andar de puntillas y se pierde la sensibilidad de la planta.", []],
},
"ne-bbd6023c": {
"en": ["Which nerve supplies the external anal sphincter?",
 ["Inferior hypogastric plexus", "Obturator nerve", "Pelvic splanchnic nerves", "Genitofemoral nerve", "Pudendal nerve (inferior rectal nerve)"],
 "The voluntarily controlled external anal and external urethral sphincters are supplied by the pudendal nerve (S2–S4). The internal sphincters are smooth muscle and are controlled by autonomic nerves.", []],
"fr": ["Quel nerf innerve le muscle sphincter externe de l'anus ?",
 ["Plexus hypogastrique inférieur", "Nerf obturateur", "Nerfs splanchniques pelviens", "Nerf génitofémoral", "Nerf pudendal (nerf rectal inférieur)"],
 "Les sphincters externes de l'anus et de l'urètre, à commande volontaire, sont innervés par le nerf pudendal (S2–S4). Les sphincters internes sont des muscles lisses contrôlés par le système nerveux autonome.", []],
"de": ["Welcher Nerv innerviert den M. sphincter ani externus?",
 ["Plexus hypogastricus inferior", "N. obturatorius", "Nn. splanchnici pelvici", "N. genitofemoralis", "N. pudendus (N. rectalis inferior)"],
 "Der willkürlich steuerbare äußere Analsphinkter und der äußere Harnröhrensphinkter werden vom N. pudendus (S2–S4) innerviert. Die inneren Sphinkteren sind glatte Muskulatur und werden vegetativ gesteuert.", []],
"es": ["¿Qué nervio inerva el esfínter anal externo?",
 ["Plexo hipogástrico inferior", "Nervio obturador", "Nervios esplácnicos pélvicos", "Nervio genitofemoral", "Nervio pudendo (nervio rectal inferior)"],
 "Los esfínteres anal externo y uretral externo, de control voluntario, los inerva el nervio pudendo (S2–S4). Los esfínteres internos son músculo liso y están controlados por nervios autónomos.", []],
},
"ne-91182414": {
"en": ["The spinal (dorsal root) ganglion contains the cell bodies of which cells?",
 ["Interneurons", "Preganglionic sympathetic neurons", "Postganglionic parasympathetic neurons", "Lower motor neurons", "Pseudounipolar sensory neurons"],
 "The peripheral process of the pseudounipolar neurons in the dorsal root ganglion receives information from receptors, and the central process enters the spinal cord in the dorsal root. There are no synapses in this ganglion. The herpes zoster virus lies latent here.", []],
"fr": ["Le ganglion spinal (ganglion de la racine postérieure) contient les corps cellulaires de quelles cellules ?",
 ["Interneurones", "Neurones sympathiques préganglionnaires", "Neurones parasympathiques postganglionnaires", "Motoneurones périphériques", "Neurones sensitifs pseudo-unipolaires"],
 "Le prolongement périphérique des neurones pseudo-unipolaires du ganglion spinal reçoit les informations des récepteurs ; le prolongement central entre dans la moelle par la racine postérieure. Il n'y a pas de synapse dans ce ganglion. Le virus du zona y reste latent.", []],
"de": ["Die Zellkörper welcher Zellen enthält das Spinalganglion (Hinterwurzelganglion)?",
 ["Interneurone", "Präganglionäre sympathische Neurone", "Postganglionäre parasympathische Neurone", "Untere Motoneurone", "Pseudounipolare sensible Neurone"],
 "Der periphere Fortsatz der pseudounipolaren Neurone im Spinalganglion nimmt Informationen von Rezeptoren auf, der zentrale Fortsatz tritt mit der Hinterwurzel ins Rückenmark ein. In diesem Ganglion gibt es keine Synapsen. Das Varizella-Zoster-Virus persistiert hier latent.", []],
"es": ["¿Los cuerpos de qué células contiene el ganglio espinal (ganglio de la raíz dorsal)?",
 ["Interneuronas", "Neuronas simpáticas preganglionares", "Neuronas parasimpáticas posganglionares", "Motoneuronas inferiores", "Neuronas sensitivas seudounipolares"],
 "La prolongación periférica de las neuronas seudounipolares del ganglio espinal recibe información de los receptores y la central entra en la médula por la raíz dorsal. En este ganglio no hay sinapsis. El virus del herpes zóster permanece latente aquí.", []],
},
}
